        let app = build_app(gate).expect("app builds");

        let result = TestHarness::new()
            .interactive_stdin()
            .prompts(Arc::new(ScriptedResponder::new([
                PromptResponse::text("Not_A_Name"),
                PromptResponse::text("mysite"),
                PromptResponse::text(""),
                PromptResponse::text(""),
            ])))
            .run(&app, Cli::command(), args);

        result.assert_success();
        result.assert_stdout_eq("provisioned mysite in eu (public: no)\n");
    }

    #[test]
    #[serial]
    fn end_of_input_during_collection_is_an_input_error() {
        let raw: Vec<OsString> = ["formlike", "provision", "--yes"]
            .iter()
            .map(OsString::from)
            .collect();
        let (args, gate) = take_over_confirmation(raw);
        let app = build_app(gate).expect("app builds");

        let result = TestHarness::new()
            .interactive_stdin()
            .prompts(Arc::new(ScriptedResponder::new([
                PromptResponse::text("mysite"),
                PromptResponse::Cancel,
            ])))
            .run(&app, Cli::command(), args);

        result.assert_error();
        result.assert_stdout_eq("");
    }

    // -- the confirmation gate ----------------------------------------------

    #[test]
    fn the_user_asking_for_yes_stands_the_gate_down() {
        let raw: Vec<OsString> = ["formlike", "provision", "--answers", "s.txt", "--yes"]
            .iter()
            .map(OsString::from)
            .collect();
        let (args, gate) = take_over_confirmation(raw);
        assert!(!gate.required);
        assert_eq!(args.iter().filter(|a| *a == "--yes").count(), 1);
    }

    #[test]
    fn a_run_without_yes_still_reaches_the_framework_with_one() {
        let raw: Vec<OsString> = ["formlike", "provision", "--answers", "s.txt"]
            .iter()
            .map(OsString::from)
            .collect();
        let (args, gate) = take_over_confirmation(raw);
        assert!(gate.required);
        assert_eq!(
            args,
            ["formlike", "provision", "--yes", "--answers", "s.txt"]
                .iter()
                .map(OsString::from)
                .collect::<Vec<_>>()
        );
    }

    #[test]
    fn the_questions_sheet_is_left_alone() {
        let raw: Vec<OsString> = ["formlike", "provision", "questions"]
            .iter()
            .map(OsString::from)
            .collect();
        let (args, gate) = take_over_confirmation(raw);
        assert!(!gate.required);
        assert!(!args.iter().any(|a| a == "--yes"));
    }

    #[test]
    fn a_help_display_is_left_alone() {
        for line in [
            vec!["formlike", "provision", "--help"],
            vec!["formlike", "--help"],
            vec!["formlike", "provision", "-h"],
        ] {
            let raw: Vec<OsString> = line.iter().map(OsString::from).collect();
            let (args, gate) = take_over_confirmation(raw.clone());
            assert!(!gate.required, "{line:?}");
            assert_eq!(args, raw, "{line:?}");
        }
    }

    #[test]
    fn an_option_still_wanting_its_value_does_not_swallow_the_flag() {
        let raw: Vec<OsString> = ["formlike", "provision", "--answers"]
            .iter()
            .map(OsString::from)
            .collect();
        let (args, _) = take_over_confirmation(raw);
        assert_eq!(args.last().unwrap(), "--answers");
    }
}

