use std::io::IsTerminal;

use clap::{ArgMatches, CommandFactory, Parser, Subcommand};
use serde::Serialize;
use standout::cli::{App, CommandContext, CommandContextInput, Output};
use standout::handler;
use standout_dispatch::{extract_command_path, get_deepest_matches, HookError};

#[derive(Parser)]
#[command(name = "formlike")]
struct Cli {
    #[command(subcommand)]
    command: Commands,
}

#[derive(Subcommand)]
enum Commands {
    /// Provision a site from the questionnaire.
    Provision,
}

/// Runs before the questionnaire resolves. Interactive collection is the only
/// remaining answer source once `--answers` is absent, and it needs an attended
/// terminal; without one the run can never succeed, so refuse here with a
/// message that names the flag which would have unblocked it rather than
/// letting the collector report a bare "no input".
fn require_answer_source(matches: &ArgMatches, _ctx: &mut CommandContext) -> Result<(), HookError> {
    // `provision questions` only renders the blank sheet; it answers nothing.
    if extract_command_path(matches).iter().any(|s| s == "questions") {
        return Ok(());
    }

    // `--answers` is declared by the framework, not by our clap surface, so its
    // argument id belongs to the framework too. Match it by shape instead of
    // spelling it out: `ids()` only yields arguments the invocation supplied.
    let deepest = get_deepest_matches(matches);
    let has_answers = deepest.ids().any(|id| id.as_str().contains("answers"));

    if has_answers || std::io::stdin().is_terminal() {
        return Ok(());
    }

    Err(HookError::pre_dispatch(
        "no answers were supplied and stdin is not an attended terminal, so the \
         questions <id:name>, <id:region> and <id:public> cannot be asked; supply a \
         completed answer sheet with --answers FILE, or pipe one in with --answers - \
         (render a blank sheet with `formlike provision questions`); nothing was run",
    ))
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, standout::QuestionnaireChoices)]
pub enum Region {
    #[question(rename = "eu")]
    Eu,
    #[question(rename = "us")]
    Us,
}

#[derive(Debug, Clone, PartialEq, Eq, standout::Questionnaire)]
#[question(id = "formlike.provision")]
pub struct ProvisionAnswers {
    /// What is the site name?
    #[question(validate = validate_name, revision = "name.v1")]
    name: String,

    /// Which region?
    #[question(choice, default = "eu")]
    region: Region,

    /// Should the site be public?
    #[question(default = "no")]
    public: bool,
}

fn validate_name(value: &standout::input::questionnaire::AnswerValue) -> Result<(), String> {
    let text = value.as_text().unwrap_or_default();
    if text
        .chars()
        .all(|ch| ch.is_ascii_lowercase() || ch.is_ascii_digit() || ch == '-')
    {
        Ok(())
    } else {
        Err("site name may only contain lowercase letters, digits, and hyphens".into())
    }
}

#[derive(Serialize)]
pub struct ProvisionView {
    name: String,
    region: String,
    public: String,
}

mod handlers {
    use super::*;

    #[handler]
    pub fn provision(
        #[ctx] ctx: &CommandContext,
    ) -> Result<Output<ProvisionView>, anyhow::Error> {
        let answers: &ProvisionAnswers = ctx.questionnaire()?;
        Ok(Output::Render(ProvisionView {
            name: answers.name.clone(),
            region: match answers.region {
                Region::Eu => "eu".to_string(),
                Region::Us => "us".to_string(),
            },
            public: if answers.public { "yes" } else { "no" }.to_string(),
        }))
    }
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let app = App::builder()
        .templates(standout::embed_templates!("src/templates"))
        .command_with("provision", handlers::provision_Handler, |cfg| {
            cfg.template_name("provision")
                // Ordering is the point: this guard must see the invocation
                // before the questionnaire tries — and fails — to collect.
                .pre_dispatch(require_answer_source)
                .questionnaire::<ProvisionAnswers>()
        })?
        .build()?;

    app.run(Cli::command(), std::env::args());
    Ok(())
}

