//! `formlike` provisions a (pretend) site from a three-question questionnaire.
//!
//! The design centre is the unattended run: a completed answer sheet arrives
//! through `--answers`, `--yes` waives the confirmation, and the run either
//! prints its one success line or fails promptly with a diagnostic naming what
//! was missing. Interactive collection is the fallback for an attended
//! terminal, not the shape everything else bends around.

use std::ffi::OsString;
use std::io::{IsTerminal, Write};

use clap::{ArgMatches, CommandFactory, Parser, Subcommand};
use serde::Serialize;
use standout::cli::{App, CommandContext, CommandContextInput, Output};
use standout::handler;
use standout_dispatch::{extract_command_path, get_deepest_matches, HookError};

// ---------------------------------------------------------------------------
// CLI surface
// ---------------------------------------------------------------------------

#[derive(Parser)]
#[command(name = "formlike")]
struct Cli {
    #[command(subcommand)]
    command: Commands,
}

#[derive(Subcommand)]
enum Commands {
    /// Provision a site from the questionnaire.
    ///
    /// Standout attaches the answer-sheet surface to this command: the
    /// `questions` subcommand, `--answers FILE` / `--answers -`, and `--yes`.
    Provision,
}

// ---------------------------------------------------------------------------
// The questionnaire
// ---------------------------------------------------------------------------

#[derive(Debug, Clone, Copy, PartialEq, Eq, standout::QuestionnaireChoices)]
pub enum Region {
    #[question(rename = "eu")]
    Eu,
    #[question(rename = "us")]
    Us,
}

impl Region {
    fn as_str(self) -> &'static str {
        match self {
            Region::Eu => "eu",
            Region::Us => "us",
        }
    }
}

/// The field names are the stable `<id:...>` tags the answer sheet is keyed by.
/// Prompt wording above each one is cosmetic and may be reworded freely.
#[derive(Debug, Clone, PartialEq, Eq, standout::Questionnaire)]
#[question(id = "formlike.provision")]
pub struct ProvisionAnswers {
    /// What is the site name?
    #[question(validate = validate_name, revision = "name.lowercase-digits-hyphens.v1")]
    name: String,

    /// Which region?
    #[question(choice, default = "eu")]
    region: Region,

    /// Should the site be public?
    #[question(default = "no")]
    public: bool,
}

fn validate_name(value: &standout::input::questionnaire::AnswerValue) -> Result<(), String> {
    let text = value.as_text().unwrap_or_default();
    if text
        .chars()
        .all(|ch| ch.is_ascii_lowercase() || ch.is_ascii_digit() || ch == '-')
    {
        Ok(())
    } else {
        Err("the site name may use only lowercase letters, digits, and hyphens".into())
    }
}

// ---------------------------------------------------------------------------
// Gates that run before the handler
// ---------------------------------------------------------------------------

/// Runs *before* the questionnaire resolves.
///
/// With no `--answers`, interactive collection is the only remaining source and
/// it needs an attended terminal. Without one the run cannot succeed no matter
/// how long it waits, so refuse here — and name the flag that would have
/// unblocked it, which the collector's own "no input" report does not.
fn require_answer_source(matches: &ArgMatches, ctx: &mut CommandContext) -> Result<(), HookError> {
    // `provision questions` only renders the blank sheet; it answers nothing.
    if extract_command_path(matches).iter().any(|s| s == "questions") {
        return Ok(());
    }

    // `--answers` is declared by the framework rather than by our own clap
    // surface, so its argument id belongs to the framework too. Match it by
    // shape: `ids()` yields only the arguments this invocation supplied.
    let deepest = get_deepest_matches(matches);
    let has_answers = deepest.ids().any(|id| id.as_str().contains("answers"));

    if has_answers || ctx.input_sources().stdin().is_terminal() {
        return Ok(());
    }

    Err(HookError::pre_dispatch(
        "no answers were supplied and stdin is not an attended terminal, so the questions \
         <id:name>, <id:region> and <id:public> cannot be asked: pass --answers FILE with a \
         completed answer sheet, or pipe one in with --answers - (render a blank sheet with \
         `formlike provision questions`); nothing was provisioned",
    ))
}

/// Whether this invocation still owes the user a confirmation.
///
/// See [`take_over_confirmation`] for why the application asks rather than the
/// framework.
#[derive(Debug, Clone, Copy)]
pub struct ConfirmGate {
    required: bool,
}

/// Runs *after* the questionnaire resolves, so a declined run has still
/// collected nothing but has provisioned nothing either — the handler, which
/// owns the side effect, never runs.
fn confirm_provisioning(_matches: &ArgMatches, ctx: &mut CommandContext) -> Result<(), HookError> {
    let gate = *ctx
        .app_state
        .get_required::<ConfirmGate>()
        .map_err(|error| HookError::pre_dispatch(error.to_string()))?;
    if !gate.required {
        return Ok(());
    }

    // Piped stdin never confirms, and neither does an absent terminal. Ask the
    // framework's stdin seam rather than the process directly, so this agrees
    // with whatever the questionnaire itself just read from.
    if !ctx.input_sources().stdin().is_terminal() {
        return Err(HookError::pre_dispatch(
            "provisioning needs a confirmation and stdin is not an attended terminal, so the \
             question cannot be asked: pass --yes to provision without confirming; nothing was \
             provisioned",
        ));
    }

    // The prompt belongs on stderr: stdout carries the success line alone.
    eprint!("Provision this site? [y/N] ");
    let _ = std::io::stderr().flush();

    let mut line = String::new();
    match std::io::stdin().read_line(&mut line) {
        // End of input is not an answer, so it is not a confirmation.
        Ok(0) => Err(declined()),
        Ok(_) => match line.trim().to_ascii_lowercase().as_str() {
            "yes" | "y" => Ok(()),
            _ => Err(declined()),
        },
        Err(error) => Err(HookError::pre_dispatch(format!(
            "could not read the confirmation answer: {error}; nothing was provisioned"
        ))),
    }
}

fn declined() -> HookError {
    HookError::pre_dispatch("declined at the confirmation prompt; nothing was provisioned")
}

/// Standout's built-in confirmation gate accepts only the literal `yes`, but
/// this CLI must also accept `y`, in any casing. So the application takes the
/// gate over: every provisioning run is handed `--yes`, which stands the
/// framework's gate down, and [`confirm_provisioning`] asks the question on the
/// framework's behalf. The returned flag says whether the *user* asked to skip
/// confirming, which is the fact the gate actually needs.
///
/// The flag is inserted directly after `provision` rather than appended, so a
/// line ending in an option that still wants its value (`provision --answers`)
/// stays the usage error it is instead of swallowing `--yes` as that value.
fn take_over_confirmation(raw: impl IntoIterator<Item = OsString>) -> (Vec<OsString>, ConfirmGate) {
    let mut args = raw.into_iter();
    let mut out: Vec<OsString> = args.by_ref().take(1).collect();
    let rest: Vec<OsString> = args.collect();

    // Only a real provisioning run has a confirmation to skip. `questions`
    // renders a sheet, and a help or version display is clap's own.
    let is_provisioning = rest.first().is_some_and(|arg| arg == "provision")
        && !rest.iter().any(|arg| {
            arg == "questions" || arg == "--help" || arg == "-h" || arg == "--version" || arg == "-V"
        });

    if !is_provisioning {
        out.extend(rest);
        return (out, ConfirmGate { required: false });
    }

    let required = !rest.iter().any(|arg| arg == "--yes");
    let mut rest = rest.into_iter();
    out.extend(rest.by_ref().take(1)); // `provision`
    if required {
        out.push(OsString::from("--yes"));
    }
    out.extend(rest);

