}

impl Region {
    fn as_str(self) -> &'static str {
        match self {
            Region::Eu => "eu",
            Region::Us => "us",
        }
    }
}

/// The field names are the stable `<id:...>` tags the answer sheet is keyed by.
/// Prompt wording above each one is cosmetic and may be reworded freely.
#[derive(Debug, Clone, PartialEq, Eq, standout::Questionnaire)]
#[question(id = "formlike.provision")]
pub struct ProvisionAnswers {
    /// What is the site name?
    #[question(validate = validate_name, revision = "name.lowercase-digits-hyphens.v1")]
    name: String,

    /// Which region?
    #[question(choice, default = "eu")]
    region: Region,

    /// Should the site be public?
    #[question(default = "no")]
    public: bool,
}

fn validate_name(value: &standout::input::questionnaire::AnswerValue) -> Result<(), String> {
    let text = value.as_text().unwrap_or_default();
    if text
        .chars()
        .all(|ch| ch.is_ascii_lowercase() || ch.is_ascii_digit() || ch == '-')
    {
        Ok(())
    } else {
        Err("the site name may use only lowercase letters, digits, and hyphens".into())
    }
}

// ---------------------------------------------------------------------------
// Gates that run before the handler
// ---------------------------------------------------------------------------

/// Runs *before* the questionnaire resolves.
///
/// With no `--answers`, interactive collection is the only remaining source and
/// it needs an attended terminal. Without one the run cannot succeed no matter
/// how long it waits, so refuse here — and name the flag that would have
/// unblocked it, which the collector's own "no input" report does not.
fn require_answer_source(matches: &ArgMatches, ctx: &mut CommandContext) -> Result<(), HookError> {
    // `provision questions` only renders the blank sheet; it answers nothing.
    if extract_command_path(matches).iter().any(|s| s == "questions") {
        return Ok(());
    }

    // `--answers` is declared by the framework rather than by our own clap
    // surface, so its argument id belongs to the framework too. Match it by
    // shape: `ids()` yields only the arguments this invocation supplied.
    let deepest = get_deepest_matches(matches);
    let has_answers = deepest.ids().any(|id| id.as_str().contains("answers"));

    if has_answers || ctx.input_sources().stdin().is_terminal() {
        return Ok(());
    }

    Err(HookError::pre_dispatch(
        "no answers were supplied and stdin is not an attended terminal, so the questions \
         <id:name>, <id:region> and <id:public> cannot be asked: pass --answers FILE with a \
         completed answer sheet, or pipe one in with --answers - (render a blank sheet with \
         `formlike provision questions`); nothing was provisioned",
    ))
}

/// Whether this invocation still owes the user a confirmation.
///
/// See [`take_over_confirmation`] for why the application asks rather than the
/// framework.
#[derive(Debug, Clone, Copy)]
pub struct ConfirmGate {
    required: bool,
}

/// Runs *after* the questionnaire resolves, so a declined run has still
/// collected nothing but has provisioned nothing either — the handler, which
/// owns the side effect, never runs.
fn confirm_provisioning(_matches: &ArgMatches, ctx: &mut CommandContext) -> Result<(), HookError> {
    let gate = *ctx
        .app_state
        .get_required::<ConfirmGate>()
        .map_err(|error| HookError::pre_dispatch(error.to_string()))?;
    if !gate.required {
        return Ok(());
    }

    // Piped stdin never confirms, and neither does an absent terminal. Ask the
    // framework's stdin seam rather than the process directly, so this agrees
    // with whatever the questionnaire itself just read from.
    if !ctx.input_sources().stdin().is_terminal() {
        return Err(HookError::pre_dispatch(
            "provisioning needs a confirmation and stdin is not an attended terminal, so the \
             question cannot be asked: pass --yes to provision without confirming; nothing was \
             provisioned",
        ));
    }

    // The prompt belongs on stderr: stdout carries the success line alone.
    eprint!("Provision this site? [y/N] ");
    let _ = std::io::stderr().flush();

    let mut line = String::new();
    match std::io::stdin().read_line(&mut line) {
        // End of input is not an answer, so it is not a confirmation.
        Ok(0) => Err(declined()),
        Ok(_) => match line.trim().to_ascii_lowercase().as_str() {
            "yes" | "y" => Ok(()),
            _ => Err(declined()),
        },
        Err(error) => Err(HookError::pre_dispatch(format!(
            "could not read the confirmation answer: {error}; nothing was provisioned"
        ))),
    }
}

fn declined() -> HookError {
    HookError::pre_dispatch("declined at the confirmation prompt; nothing was provisioned")
}

/// Standout's built-in confirmation gate accepts only the literal `yes`, but
/// this CLI must also accept `y`, in any casing. So the application takes the
/// gate over: every provisioning run is handed `--yes`, which stands the
/// framework's gate down, and [`confirm_provisioning`] asks the question on the
/// framework's behalf. The returned flag says whether the *user* asked to skip
/// confirming, which is the fact the gate actually needs.
///
/// Placement matters twice over. Clap echoes the arguments it already accepted
/// in the usage line of a parse error, so a flag wedged in front of a typo makes
/// that line read as though `--yes` were required — hence: append. The one shape
/// appending would break is a line ending in an option still waiting for its
/// value (`provision --answers`), where the flag would be read as that value
/// instead of leaving the usage error alone — hence: not quite always.
fn take_over_confirmation(raw: impl IntoIterator<Item = OsString>) -> (Vec<OsString>, ConfirmGate) {
    let mut args = raw.into_iter();
    let mut out: Vec<OsString> = args.by_ref().take(1).collect();
    let rest: Vec<OsString> = args.collect();

    // Only a real provisioning run has a confirmation to skip. `questions`
    // renders a sheet, and a help or version display is clap's own.
    let is_provisioning = rest.first().is_some_and(|arg| arg == "provision")
        && !rest.iter().any(|arg| {
            arg == "questions" || arg == "--help" || arg == "-h" || arg == "--version" || arg == "-V"
        });

    if !is_provisioning {
        out.extend(rest);
        return (out, ConfirmGate { required: false });
    }

    let required = !rest.iter().any(|arg| arg == "--yes");
    if !required {
        out.extend(rest);
        return (out, ConfirmGate { required });
    }

    // A bare `-` is `--answers`' stdin spelling, not an option awaiting a value,
    // and anything carrying `=` already has its value attached.
    let tail_wants_a_value = rest.last().is_some_and(|arg| {
        let arg = arg.to_string_lossy();
        arg.starts_with('-') && arg.len() > 1 && !arg.contains('=')
    });

    let insert_at = if tail_wants_a_value {
        rest.len() - 1
    } else {
        rest.len()
    };
    let mut rest = rest;
    let tail = rest.split_off(insert_at);
    out.extend(rest);
    out.push(OsString::from("--yes"));
    out.extend(tail);

    (out, ConfirmGate { required })
}

// ---------------------------------------------------------------------------
// Handler
// ---------------------------------------------------------------------------

#[derive(Serialize)]
pub struct ProvisionView {
    name: String,
    region: String,
    public: String,
}

mod handlers {
    use super::*;

    #[handler]
    pub fn provision(#[ctx] ctx: &CommandContext) -> Result<Output<ProvisionView>, anyhow::Error> {
        let answers: &ProvisionAnswers = ctx.questionnaire()?;
        Ok(Output::Render(ProvisionView {
            name: answers.name.clone(),
            region: answers.region.as_str().to_string(),
            public: if answers.public { "yes" } else { "no" }.to_string(),
        }))
    }
}

// ---------------------------------------------------------------------------
// Wiring
// ---------------------------------------------------------------------------

fn build_app(gate: ConfirmGate) -> Result<App, Box<dyn std::error::Error>> {
    let app = App::builder()
        .templates(standout::embed_templates!("src/templates"))
        .app_state(gate)
        .command_with("provision", handlers::provision_Handler, |cfg| {
            // Ordering is the point. The guard has to see the invocation before
            // the questionnaire tries and fails to collect; the confirmation
            // has to come after the answers exist.
            cfg.template_name("provision")
                .pre_dispatch(require_answer_source)
                .questionnaire::<ProvisionAnswers>()
                .pre_dispatch(confirm_provisioning)
        })?
        .build()?;
    Ok(app)
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let (args, gate) = take_over_confirmation(std::env::args_os());
    let app = build_app(gate)?;
    app.run(Cli::command(), args);
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;
    use standout::input::{PromptResponse, ScriptedResponder};
    use standout_test::{serial, TestHarness};
    use std::sync::Arc;

    /// Mirror what `main` does, so tests exercise the same argv the shell
    /// would produce.
    fn run(argv: &[&str]) -> (standout_test::TestResult, ConfirmGate) {
        let raw: Vec<OsString> = std::iter::once("formlike")
            .chain(argv.iter().copied())
            .map(OsString::from)
            .collect();
        let (args, gate) = take_over_confirmation(raw);
        let app = build_app(gate).expect("app builds");
        let result = TestHarness::new().run(&app, Cli::command(), args);
        (result, gate)
    }

    fn sheet(name: &str, region: &str, public: &str) -> String {
        let blank = blank_sheet();
        let fingerprint = blank
            .lines()
            .find(|l| l.starts_with("#! fingerprint"))
            .expect("sheet carries a fingerprint");
        format!(
            "#! standout-answers 1\n#! questionnaire: formlike.provision\n{fingerprint}\n\n\
             1. What is the site name? (string) <id:name>\n{name}\n\n\
             2. Which region? (eu or us) <id:region>\n{region}\n\n\
             3. Should the site be public? (bool) <id:public>\n{public}\n"
        )
    }

    fn blank_sheet() -> String {
        let (result, _) = run(&["provision", "questions"]);
        result.stdout().to_string()
    }

    // -- the answer-sheet surface -------------------------------------------

    #[test]
    #[serial]
    fn questions_prints_a_sheet_carrying_every_stable_id() {
        let (result, _) = run(&["provision", "questions"]);
        result.assert_success();

        let out = result.stdout();
        for id in ["<id:name>", "<id:region>", "<id:public>"] {
            let line = out
                .lines()
                .find(|l| l.contains(id))
                .unwrap_or_else(|| panic!("no question line for {id} in:\n{out}"));
            assert!(
                line.trim_end().ends_with(id),
                "the tag must be the last content on the line: {line:?}"
            );
        }
    }

    #[test]
    #[serial]
    fn a_sheet_on_stdin_provisions_and_says_so_once() {
        let raw: Vec<OsString> = ["formlike", "provision", "--answers", "-", "--yes"]
            .iter()
            .map(OsString::from)
            .collect();
        let (args, gate) = take_over_confirmation(raw);
        let app = build_app(gate).expect("app builds");

        let result = TestHarness::new()
            .piped_stdin(&sheet("mysite", "us", "yes"))
            .run(&app, Cli::command(), args);

        result.assert_success();
        result.assert_stdout_eq("provisioned mysite in us (public: yes)");
    }

    #[test]
    #[serial]
    fn blank_answers_take_the_declared_defaults() {
        let raw: Vec<OsString> = ["formlike", "provision", "--answers", "-", "--yes"]
            .iter()
            .map(OsString::from)
            .collect();
        let (args, gate) = take_over_confirmation(raw);
        let app = build_app(gate).expect("app builds");

        let result = TestHarness::new()
            .piped_stdin(&sheet("mysite", "", ""))
            .run(&app, Cli::command(), args);

        result.assert_success();
        result.assert_stdout_eq("provisioned mysite in eu (public: no)");
    }

    fn assert_sheet_rejected(name: &str, region: &str, public: &str, mentions: &str) {
        let raw: Vec<OsString> = ["formlike", "provision", "--answers", "-", "--yes"]
            .iter()
            .map(OsString::from)
            .collect();
        let (args, gate) = take_over_confirmation(raw);
        let app = build_app(gate).expect("app builds");

        let result = TestHarness::new()
            .piped_stdin(&sheet(name, region, public))
            .run(&app, Cli::command(), args);

        result.assert_error();
        result.assert_stdout_eq("");
        let error = result.error().unwrap_or_default().to_string();
        assert!(
            error.contains(mentions),
            "expected the diagnostic to name {mentions:?}, got: {error}"
        );
    }

    #[test]
    #[serial]
    fn a_missing_required_answer_names_its_question() {
        assert_sheet_rejected("", "eu", "no", "name");
    }

    #[test]
    #[serial]
    fn an_ill_formed_name_names_its_question() {
        assert_sheet_rejected("Not_A_Name", "eu", "no", "name");
    }

    #[test]
    #[serial]
    fn an_unlisted_region_names_its_question() {
        assert_sheet_rejected("mysite", "asia", "no", "region");
    }

    #[test]
    #[serial]
    fn a_non_bool_public_answer_names_its_question() {
        assert_sheet_rejected("mysite", "eu", "maybe", "public");
    }

    // -- interactive collection ---------------------------------------------

    #[test]
    #[serial]
    fn interactive_collection_asks_every_question_in_order() {
        let raw: Vec<OsString> = ["formlike", "provision", "--yes"]
            .iter()
            .map(OsString::from)
            .collect();
        let (args, gate) = take_over_confirmation(raw);
        let app = build_app(gate).expect("app builds");

        let result = TestHarness::new()
            .interactive_stdin()
            .prompts(Arc::new(ScriptedResponder::new([
                PromptResponse::text("mysite"),
                PromptResponse::text("us"),
                PromptResponse::text("yes"),
            ])))
            .run(&app, Cli::command(), args);

        result.assert_success();
        result.assert_stdout_eq("provisioned mysite in us (public: yes)");
    }

    #[test]
    #[serial]
    fn interactive_collection_re_asks_a_rejected_answer() {
        let raw: Vec<OsString> = ["formlike", "provision", "--yes"]
            .iter()
            .map(OsString::from)
            .collect();
        let (args, gate) = take_over_confirmation(raw);
        let app = build_app(gate).expect("app builds");

        let result = TestHarness::new()
            .interactive_stdin()
            .prompts(Arc::new(ScriptedResponder::new([
                PromptResponse::text("Not_A_Name"),
                PromptResponse::text("mysite"),
                PromptResponse::text(""),
                PromptResponse::text(""),
            ])))
            .run(&app, Cli::command(), args);

        result.assert_success();
        result.assert_stdout_eq("provisioned mysite in eu (public: no)");
    }

    #[test]
    #[serial]
    fn end_of_input_during_collection_is_an_input_error() {
        let raw: Vec<OsString> = ["formlike", "provision", "--yes"]
            .iter()
            .map(OsString::from)
            .collect();
        let (args, gate) = take_over_confirmation(raw);
        let app = build_app(gate).expect("app builds");

        let result = TestHarness::new()
            .interactive_stdin()
            .prompts(Arc::new(ScriptedResponder::new([
                PromptResponse::text("mysite"),
                PromptResponse::Cancel,
            ])))
            .run(&app, Cli::command(), args);

        result.assert_error();
        result.assert_stdout_eq("");
    }

    #[test]
    #[serial]
    fn interactive_collection_re_asks_a_blank_required_answer() {
        let raw: Vec<OsString> = ["formlike", "provision", "--yes"]
            .iter()
            .map(OsString::from)
            .collect();
        let (args, gate) = take_over_confirmation(raw);
        let app = build_app(gate).expect("app builds");

        let result = TestHarness::new()
            .interactive_stdin()
            .prompts(Arc::new(ScriptedResponder::new([
                PromptResponse::text(""), // blank: `name` has no default, so re-ask
                PromptResponse::text("site2"),
                PromptResponse::text(""),
                PromptResponse::text(""),
            ])))
            .run(&app, Cli::command(), args);

        result.assert_success();
        result.assert_stdout_eq("provisioned site2 in eu (public: no)");
    }

    // -- the confirmation gate ----------------------------------------------

    #[test]
    #[serial]
    fn a_confirmation_that_cannot_be_asked_names_the_flag_that_waives_it() {
        let raw: Vec<OsString> = ["formlike", "provision", "--answers", "-"]
            .iter()
            .map(OsString::from)
            .collect();
        let (args, gate) = take_over_confirmation(raw);
        assert!(gate.required);
        let app = build_app(gate).expect("app builds");

        let result = TestHarness::new()
            .piped_stdin(&sheet("mysite", "eu", "no"))
            .run(&app, Cli::command(), args);

        result.assert_error();
        result.assert_stdout_eq("");
        let error = result.error().unwrap_or_default().to_string();
        assert!(
            error.contains("--yes"),
            "expected the diagnostic to name --yes, got: {error}"
        );
    }


    #[test]
    fn the_user_asking_for_yes_stands_the_gate_down() {
        let raw: Vec<OsString> = ["formlike", "provision", "--answers", "s.txt", "--yes"]
            .iter()
            .map(OsString::from)
            .collect();
        let (args, gate) = take_over_confirmation(raw);
        assert!(!gate.required);
        assert_eq!(args.iter().filter(|a| *a == "--yes").count(), 1);
    }

    #[test]
    fn a_run_without_yes_still_reaches_the_framework_with_one() {
        let raw: Vec<OsString> = ["formlike", "provision", "--answers", "s.txt"]
            .iter()
            .map(OsString::from)
            .collect();
        let (args, gate) = take_over_confirmation(raw);
        assert!(gate.required);
        assert_eq!(
            args,
            ["formlike", "provision", "--yes", "--answers", "s.txt"]
                .iter()
                .map(OsString::from)
                .collect::<Vec<_>>()
        );
    }

    #[test]
    fn the_questions_sheet_is_left_alone() {
        let raw: Vec<OsString> = ["formlike", "provision", "questions"]
            .iter()
            .map(OsString::from)
            .collect();
        let (args, gate) = take_over_confirmation(raw);
        assert!(!gate.required);
        assert!(!args.iter().any(|a| a == "--yes"));
    }

    #[test]
    fn a_help_display_is_left_alone() {
        for line in [
            vec!["formlike", "provision", "--help"],
            vec!["formlike", "--help"],
            vec!["formlike", "provision", "-h"],
        ] {
            let raw: Vec<OsString> = line.iter().map(OsString::from).collect();
            let (args, gate) = take_over_confirmation(raw.clone());
            assert!(!gate.required, "{line:?}");
            assert_eq!(args, raw, "{line:?}");
        }
    }

    #[test]
    fn an_option_still_wanting_its_value_does_not_swallow_the_flag() {
        let raw: Vec<OsString> = ["formlike", "provision", "--answers"]
            .iter()
            .map(OsString::from)
            .collect();
        let (args, _) = take_over_confirmation(raw);
        assert_eq!(args.last().unwrap(), "--answers");
    }
}

